/**
 * Essay charts, mosaic, explorer, specimens — extracted from index.html.
 * Requires window.t + pipeline globals from data/*.js (via legacy-bridge.js).
 */
const t = (key, vars) => window.t(key, vars);

function pipelineData() {
  return {
    DECADES: window.DECADES,
    RIVER: window.RIVER,
    TYPO: window.TYPO,
    BLOOD_PIXEL: window.BLOOD_PIXEL,
    BLOOD_SEMANTIC: window.BLOOD_SEMANTIC,
    MAIN_DEC: window.MAIN_DEC,
    DARK_PTS: window.DARK_PTS,
    RED_PTS: window.RED_PTS,
    FACE_PTS: window.FACE_PTS,
    TEXT_PTS: window.TEXT_PTS,
    SYM_PTS: window.SYM_PTS,
    DIAG_PTS: window.DIAG_PTS,
    SERIES_CI: window.SERIES_CI,
    CENSUS_SERIES: window.CENSUS_SERIES,
    POSTERS: window.POSTERS,
  };
}

let {
  DECADES,
  RIVER,
  TYPO,
  BLOOD_PIXEL,
  BLOOD_SEMANTIC,
  MAIN_DEC,
  DARK_PTS,
  RED_PTS,
  FACE_PTS,
  TEXT_PTS,
  SYM_PTS,
  DIAG_PTS,
  SERIES_CI,
  CENSUS_SERIES,
  POSTERS,
} = pipelineData();
